function ic(n,c){return '<span class="ico'+(c?' '+c:'')+'">'+(ICONS[n]||'')+'</span>'}
function icon(name,cls=''){return `<span class="${cls||'game-icon'}">${ICONS[name]||ICONS.spade}</span>`}

