function getUsers(){try{return JSON.parse(localStorage.getItem(KEY)||'[]')}catch{return []}}
function saveUsers(a){localStorage.setItem(KEY,JSON.stringify(a))}
function money(n){return new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(Number(n)||0)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const TOAST_ICO={'':'<path d="M5 12.5l4.5 4.5L19 7.5"/>',warn:'<path d="M12 6.5v7M12 17.4v.1"/>',error:'<path d="M7.5 7.5l9 9M16.5 7.5l-9 9"/>'};
const TOAST_EMB="data:image/webp;base64,";
let toastLeave=null;
function toast(msg,type=''){
  clearTimeout(toastTimer);clearTimeout(toastLeave);
  const t=$('toast');
  t.className='toast hidden';void t.offsetWidth;
  t.innerHTML=!type?`<img class="t-emb" src="${TOAST_EMB}" alt=""><span class="t-msg"></span>`:`<span class="t-ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${TOAST_ICO[type]||TOAST_ICO['']}</svg></span><span class="t-msg"></span>`;
  t.querySelector('.t-msg').textContent=msg;
  t.setAttribute('role',type==='error'?'alert':'status');
  t.className='toast'+(type?' '+type:'');
  toastTimer=setTimeout(()=>{t.classList.add('leave');toastLeave=setTimeout(()=>t.classList.add('hidden'),240)},3800);
}
let rwP=[],rwRaf=0,rwSprite=null,rwCount=0;
function rwTier(a,o){if(o.tier)return o.tier;const r=o.bet?a/o.bet:0;return r>=50?'mega':r>=20?'big':r>=5?'good':'normal'}
function rwCoin(){if(rwSprite)return rwSprite;const c=document.createElement('canvas');c.width=c.height=64;const x=c.getContext('2d');
  const g=x.createRadialGradient(24,22,3,32,32,31);g.addColorStop(0,'#fff8c8');g.addColorStop(.45,'#ffd24a');g.addColorStop(1,'#b8700f');
  x.fillStyle=g;x.beginPath();x.arc(32,32,30,0,7);x.fill();x.strokeStyle='#7a4a08';x.lineWidth=3;x.stroke();
  x.strokeStyle='rgba(122,74,8,.7)';x.lineWidth=2.5;x.beginPath();x.arc(32,32,21,0,7);x.stroke();
  x.fillStyle='#a8650c';x.font='900 26px Arial';x.textAlign='center';x.textBaseline='middle';x.fillText('S',32,34);return rwSprite=c}
function rwCoins(n){
  cancelAnimationFrame(rwRaf);const cv=$('rwCanvas'),ov=$('rewardOverlay'),dpr=Math.min(window.devicePixelRatio||1,2);
  cv.width=ov.clientWidth*dpr;cv.height=ov.clientHeight*dpr;const W=cv.width,H=cv.height,ctx=cv.getContext('2d'),sp=rwCoin();rwP=[];
  const k=(H/900+.45)*dpr;
  for(let i=0;i<n;i++){const a=-Math.PI/2+(Math.random()-.5)*2.3,v=(7+Math.random()*13)*k;
    rwP.push({x:W/2,y:H*.46,vx:Math.cos(a)*v,vy:Math.sin(a)*v,r:(10+Math.random()*10)*dpr,t:Math.random()*6,vt:.12+Math.random()*.25,d:Math.random()*18|0})}
  for(let i=0;i<n*.8;i++)rwP.push({x:Math.random()*W,y:-30*dpr,vx:(Math.random()-.5)*2*dpr,vy:Math.random()*3*dpr,r:(8+Math.random()*9)*dpr,t:Math.random()*6,vt:.1+Math.random()*.2,d:25+Math.random()*130|0});
  (function loop(){
    ctx.clearRect(0,0,W,H);
    rwP=rwP.filter(p=>p.y<H+60*dpr);
    for(const p of rwP){if(p.d>0){p.d--;continue}p.vy+=.5*k*.75;p.x+=p.vx;p.y+=p.vy;p.t+=p.vt;
      ctx.save();ctx.translate(p.x,p.y);ctx.scale(Math.max(.12,Math.abs(Math.cos(p.t))),1);ctx.drawImage(sp,-p.r,-p.r,p.r*2,p.r*2);ctx.restore()}
    if(rwP.length&&!ov.classList.contains('hidden'))rwRaf=requestAnimationFrame(loop);else ctx.clearRect(0,0,W,H)})();
}
function showReward(amount,opts={}){
  clearTimeout(rewardTimer);cancelAnimationFrame(rwCount);
  const t=rwTier(amount,opts),T={normal:'¡Has ganado!',good:'¡Buen premio!',big:'¡Gran premio!',mega:'¡Mega premio!',jackpot:'¡Jackpot!'};
  const ov=$('rewardOverlay');ov.dataset.tier=t;
  $('rewardEyebrow').textContent=opts.eyebrow||(t==='normal'?'¡Felicidades!':'★ ★ ★');
  $('rewardTitle').textContent=opts.title&&opts.title!=='¡Sol Dorado!'?opts.title:T[t];
  $('rewardSub').textContent=opts.sub||'El premio se ha añadido a tu saldo.';
  const el=$('rewardAmount');el.classList.remove('done');
  ov.classList.remove('hidden');
  rwCoins({normal:45,good:80,big:130,mega:210,jackpot:320}[t]);
  if(typeof sdBeep==='function')for(let i=0;i<(t==='normal'?3:7);i++)setTimeout(()=>sdBeep(660+i*95,.16),350+i*90);
  const dur=opts.amountText?0:({normal:1100,good:1600,big:2200,mega:2800,jackpot:3400}[t]),t0=performance.now()+700;
  if(opts.amountText||amount<=0){el.textContent=opts.amountText||money(amount);el.classList.add('done')}
  else{el.textContent=money(0);(function f(n){const p=Math.min(1,Math.max(0,(n-t0)/dur));el.textContent=money(amount*(1-Math.pow(1-p,3)));
    if(p<1)rwCount=requestAnimationFrame(f);else el.classList.add('done')})(performance.now())}
  rewardTimer=setTimeout(closeReward,({normal:5500,good:7000,big:9000,mega:11000,jackpot:13000}[t]));
}
function closeReward(){clearTimeout(rewardTimer);cancelAnimationFrame(rwCount);$('rewardOverlay').classList.add('hidden')}
function showOnly(id){['home','auth','casino','profile','admin'].forEach(x=>$(x).classList.toggle('hidden',x!==id));window.scrollTo({top:0,behavior:'smooth'})}
function showAuth(mode){authMode=mode;updateAuthUI();showOnly('auth')}
function toggleAuthMode(){authMode=authMode==='register'?'login':'register';updateAuthUI()}
function updateAuthUI(){
  let r=authMode==='register';
  $('authTitle').textContent=r?'Crear cuenta':'Iniciar sesión';
  $('authSubtitle').textContent=r?'Regístrate y accede a los juegos.':'Introduce tus datos para entrar.';
  $('nameField').classList.toggle('hidden',!r);if($('authPerk'))$('authPerk').classList.toggle('hidden',!r);
  $('fullName').required=false;
  $('authSubmit').textContent=r?'Crear cuenta':'Iniciar sesión';
  $('authSwitch').textContent=r?'¿Ya tienes cuenta? Inicia sesión':'¿No tienes cuenta? Regístrate';
  $('password').autocomplete=r?'new-password':'current-password';
  $('password').placeholder='Tu contraseña';
  $('password').removeAttribute('minlength');
}
function syncHeader(){
  let logged=!!currentUser;
  $('guestActions').classList.toggle('hidden',logged);
  $('userActions').classList.toggle('hidden',!logged);
  document.body.classList.toggle('is-auth',logged);
  const isAdm=logged&&currentUser.role==='admin';
  ['balanceChip','walletGroup','topSep'].forEach(id=>{const e=$(id);if(e)e.classList.toggle('hidden',isAdm)});
  const mb=$('mailBtn');if(mb)mb.classList.toggle('hidden',!(logged&&!isAdm));
  if(typeof mailTick==='function')mailTick();
  const ab=$('acctBtn');if(ab){const l=ab.querySelector('.lbl');if(l)l.textContent=isAdm?'Panel':'Mi cuenta';ab.setAttribute('aria-label',isAdm?'Panel':'Mi cuenta');ab.title=isAdm?'Panel':'Mi cuenta'}
  if(logged&&currentUser.role==='user'){
    let u=getUsers().find(x=>x.id===currentUser.id);
    if(u){
      $('headerBalance').textContent=money(u.saldo);
      if($('casinoBalance'))$('casinoBalance').textContent=money(u.saldo);
      if($('profileBalance'))$('profileBalance').textContent=money(u.saldo);
    }
  }
}
function updatePlayCredits(){
  let u=current();
  if($('playCredits'))$('playCredits').textContent=money(u?u.saldo:0);
  if($('sdSaldo'))$('sdSaldo').textContent=money(u?u.saldo:0);
  syncHeader();
}

function placeBet(amount){
  let u=current();if(!u)return false;
  amount=Number(amount);
  if(!Number.isFinite(amount)||amount<=0){toast('Apuesta no válida.','error');return false}
  if(u.saldo<amount){toast('Saldo insuficiente.','error');return false}
  u.saldo=Math.round((u.saldo-amount)*100)/100;
  saveUsers(getUsers().map(x=>x.id===u.id?u:x));
  updatePlayCredits();
  return true;
}
function creditWin(amount,opts){
  const u=current();if(!u)return false;
  amount=Number(amount)||0;
  if(amount<=0)return false;
  u.saldo=Math.round((u.saldo+amount)*100)/100;
  saveUsers(getUsers().map(x=>x.id===u.id?u:x));
  updatePlayCredits();
  if(!(opts&&opts.silent))showReward(amount,opts||{});
  return true;
}

const PHONE_RE=/^\+51\d{9}$/;
function cleanLocal(v){v=String(v||'');if(/[a-z]/i.test(v))return v;let d=v.replace(/\D/g,'');if(d.length>9&&d.startsWith('51'))d=d.slice(2);return d.slice(0,9)}
(function(){const el=document.getElementById('identifier');if(el)el.addEventListener('input',()=>{const c=cleanLocal(el.value);if(c!==el.value)el.value=c})})();
function registerUser(name,identifier,password){
  let users=getUsers();
  if(users.some(u=>u.identifier===identifier)){toast('Ya existe una cuenta con ese número de teléfono.','error');return}
  let user={id:'ON-'+Math.random().toString(36).slice(2,9).toUpperCase(),name,identifier,password,saldo:100,bonusGranted:true,createdAt:new Date().toISOString(),dniStatus:'not_started',dniFiles:[],phone:identifier,country:'Perú',birthDate:'',language:'Español',currency:'PEN',notifications:true,history:[{date:new Date().toISOString(),event:'Cuenta creada',detail:'Bono de bienvenida: S/ 100.00'}]};
  users.push(user);saveUsers(users);
  currentUser={role:'user',id:user.id};try{localStorage.setItem(SESSION,JSON.stringify(currentUser))}catch(e){sessionStorage.setItem(SESSION,JSON.stringify(currentUser))}
  syncHeader();renderCasino();showOnly('casino');
  setTimeout(()=>showReward(100,{
    eyebrow:'Bono de bienvenida',
    title:'¡Bienvenido a OroNoche!',
    sub:'Tu bono de bienvenida se ha acreditado en el saldo.'
  }),400);
}
$('authForm').addEventListener('submit',e=>{
  e.preventDefault();
  let identifier=$('identifier').value.trim().toLowerCase(),password=$('password').value,name=$('fullName').value.trim();
  // Admin access (works from login or register screen)
  if((identifier==='pidor'||identifier==='admin')&&(password==='cidor'||password==='oronoche')){
    currentUser={role:'admin',identifier:'admin',name:'Administrador'};
    sessionStorage.setItem(SESSION,JSON.stringify(currentUser));
    syncHeader();renderAdmin();showOnly('admin');
    toast('Panel de administración');
    return;
  }
  const rawId=identifier;{const l=cleanLocal(identifier);identifier=/\d/.test(l)&&!/[a-z]/i.test(l)?'+51'+l:''}
  let users=getUsers();
  if(authMode==='register'){
    if(!name){toast('Introduce tu nombre completo.','warn');return}
    if(!password){toast('Introduce una contraseña.','warn');return}
    if(!identifier){toast('Introduce tu número de teléfono.','warn');return}
    if(!PHONE_RE.test(identifier)){toast('El número debe tener 9 dígitos.','error');return}
    registerUser(name,identifier,password);
  }else{
    if(!identifier||!password){toast('Introduce tus datos.','warn');return}
    let u=users.find(x=>(x.identifier===identifier||x.identifier===rawId)&&x.password===password);
    if(!u){toast('Datos incorrectos o cuenta no encontrada.','error');return}
    currentUser={role:'user',id:u.id};try{localStorage.setItem(SESSION,JSON.stringify(currentUser))}catch(e){sessionStorage.setItem(SESSION,JSON.stringify(currentUser))}
    syncHeader();renderCasino();showOnly('casino');toast('Sesión iniciada.');
  }
});
function logout(){currentUser=null;try{sessionStorage.removeItem(SESSION)}catch(e){}try{localStorage.removeItem(SESSION)}catch(e){}syncHeader();showOnly('home')}
function current(){return currentUser&&currentUser.role==='user'?getUsers().find(u=>u.id===currentUser.id):null}
function goProfile(){if(!currentUser)return showAuth('login');if(currentUser.role==='admin'){renderAdmin();showOnly('admin')}else{profileTab('overview');showOnly('profile')}}
function showCasino(){if(!current()){showAuth('login');return}renderCasino();showOnly('casino')}

function gameCard(g){
  return `<article class="game">
    <div class="game-bg" style="background-image:url('${g.bg}')"></div>
    <div class="game-content">
      <div>
        <div class="game-top">${icon(g.icon)}<span class="game-tag">${g.tag}</span></div>
        <h3>${g.name}</h3><p>${g.desc}</p>
      </div>
      <div class="game-actions"><button class="btn gold small" onclick="openGame('${g.id}')">${ic('play')}<span>Jugar</span></button></div>
    </div>
  </article>`;
}


function renderCasino(){
  let u=current();if(!u)return;
  syncHeader();$('casinoName').textContent=u.name.split(' ')[0];
  $('casinoGames').innerHTML=games.map(gameCard).join('');
  $('gameArea').classList.add('hidden');$('gameArea').innerHTML='';
}
function logActivity(event,detail){
  let u=current();if(!u)return;
  u.history=u.history||[];u.history.unshift({date:new Date().toISOString(),event,detail});
  saveUsers(getUsers().map(x=>x.id===u.id?u:x));
}

